import random
import re


MAX_N = 200_000
MAX_M = 200_000
MAX_A = 1_000_000_000
SMALL_CASES = (
    (1, (0,)),
    (1, (1_000_000_000, 0, 7)),
    (200_000, (1_000_000_000,)),
    (200_000, (999_999_999,)),
    (4, (2, 5, 0)),
    (7, (0, 7, 14, 0)),
    (5, (4, 4, 4, 4)),
    (200_000, (0, 199_999, 1, 200_000, 0, 999_999_999, 2, 0)),
)


def _decimal(token, limit):
    """Parse a decimal token, representing oversized magnitudes out of range."""
    if re.fullmatch(r"[+-]?[0-9]+", token) is None:
        return None
    digits = token.lstrip("+-").lstrip("0")
    if len(digits) > len(str(limit)):
        magnitude = limit + 1
    else:
        magnitude = int(digits or "0")
    return -magnitude if token.startswith("-") else magnitude


def _parse(inp):
    tokens = inp.split()
    if len(tokens) < 2:
        return None
    size = _decimal(tokens[0], MAX_N)
    modulus = _decimal(tokens[1], MAX_M)
    if size is None or modulus is None:
        return None
    if not (1 <= size <= MAX_N and 1 <= modulus <= MAX_M):
        return None
    if len(tokens) != size + 2:
        return None
    values = []
    for token in tokens[2:]:
        value = _decimal(token, MAX_A)
        if value is None or not 0 <= value <= MAX_A:
            return None
        values.append(value)
    return modulus, values


def _format(modulus, values):
    return f"{len(values)} {modulus}\n" + " ".join(map(str, values)) + "\n"


def validate_input(inp: str) -> bool:
    return _parse(inp) is not None


def gen_small(seed: int, n: int) -> list[str]:
    rng = random.Random(seed)
    result = []
    for index in range(n):
        if index < len(SMALL_CASES):
            modulus, values = SMALL_CASES[index]
        else:
            modulus = rng.choice((1, 2, 3, 7, MAX_M, rng.randint(1, MAX_M)))
            size = rng.randint(1, 8)
            choices = (0, 1, modulus - 1, modulus, 2 * modulus, MAX_A)
            values = [
                rng.choice(choices) if rng.randrange(2) else rng.randint(0, MAX_A)
                for _ in range(size)
            ]
        result.append(_format(modulus, values))
    return result


def gen_stress(seed: int) -> list[str]:
    rng = random.Random(seed)
    mixed = [rng.randint(0, MAX_A) for _ in range(MAX_N)]
    sparse_residues = [MAX_A] * MAX_N
    sparse_residues[MAX_N // 2] = MAX_A - 1
    return [_format(MAX_M, mixed), _format(MAX_M, sparse_residues)]


def check_postconditions(inp: str, out: str) -> list[tuple[str, str]]:
    parsed = _parse(inp)
    if parsed is None:
        return [("POST-1", "Input violates the format or bounds.")]
    modulus, values = parsed
    size = len(values)
    count = size * (size + 1) // 2
    limit = count * (modulus - 1)

    tokens = out.split()
    if len(tokens) != 1:
        return [("POST-2", "Expected exactly one integer token.")]
    answer = _decimal(tokens[0], limit)
    if answer is None:
        return [("POST-2", "The output token is not a decimal integer.")]
    if not 0 <= answer <= limit:
        return [("POST-4", f"Answer must lie between 0 and {limit}.")]

    singleton_sum = sum(value % modulus for value in values)
    upper = singleton_sum + (count - size) * (modulus - 1)
    failures = []
    if not singleton_sum <= answer <= upper:
        failures.append(("POST-4", f"Singleton contributions bound the answer to [{singleton_sum}, {upper}]."))
    elif singleton_sum == 0 and answer != 0:
        failures.append(("POST-4", "All entries are divisible by the modulus, so the answer must be zero."))

    weighted_total = sum(
        index * (size - index + 1) * value
        for index, value in enumerate(values, 1)
    )
    if (answer - weighted_total) % modulus != 0:
        failures.append(("POST-5", "Answer has the wrong residue modulo M."))
    return failures


def metamorphic_pairs(seed: int, n: int) -> list[tuple[str, str, str, str]]:
    rng = random.Random(seed)
    pairs = []
    for index in range(n):
        modulus = rng.choice((1, 2, 7, MAX_M, rng.randint(1, MAX_M)))
        values = [rng.randint(0, MAX_A) for _ in range(rng.randint(2, 7))]
        first = _format(modulus, values)
        if index % 3 == 0:
            changed = values.copy()
            position = rng.randrange(len(values))
            value = changed[position]
            changed[position] = value + modulus if value + modulus <= MAX_A else value - modulus
            pairs.append(("POST-6", "equal", first, _format(modulus, changed)))
        elif index % 3 == 1:
            pairs.append(("POST-6", "equal", first, _format(modulus, values[::-1])))
        else:
            pairs.append(("POST-7", "le", first, _format(modulus, values + [0])))
    return pairs


def reference_small(inp: str) -> str | None:
    parsed = _parse(inp)
    if parsed is None:
        return None
    modulus, values = parsed
    size = len(values)
    if size > 12:
        return None

    answer = 0
    for left in range(size):
        for right in range(left, size):
            answer += sum(values[left:right + 1]) % modulus
    return f"{answer}\n"
